<?php if(fuwari_option('tags_enable')):?><section class="card-base p-4 onload-animation" style="animation-delay:200ms"><div class="font-bold transition text-lg text-neutral-900 dark:text-neutral-100 relative ml-3 mb-2 before:absolute before:w-1 before:h-4 before:top-1 before:-left-3 before:rounded-md before:bg-[var(--primary)]"><?php echo fuwari_label('tags');?></div><div class="flex gap-2 flex-wrap"><?php foreach(get_tags(['hide_empty'=>true]) as $tag):?><a data-no-swup class="btn-regular rounded-lg px-3 py-1 text-sm" href="<?php echo esc_url(home_url('/archive/?tag='.rawurlencode($tag->slug)));?>"><?php echo esc_html($tag->name);?></a><?php endforeach;?></div></section><?php endif;?>
